import pathlib,json,hashlib,math,collections,importlib.util,numpy as np,ast
R=pathlib.Path(r'C:\tmp\disdex-d126-crossrunner-research-20261126')
P=R/'Y06_R24_SYNTHETIC_PROTOCOL_20261127.json';O=R/'Y06_R24_SYNTHETIC_RESULTS_20261127.json';assert not P.exists() and not O.exists()
src=R/'y06_r3_bear_retest_research_v2.py';sp=importlib.util.spec_from_file_location('r3',src);r3=importlib.util.module_from_spec(sp);sp.loader.exec_module(r3);bt=r3.bt;H=bt.H;M=bt.M
bt.HS=bt.MS=bt.T('2025-03-01T00:00:00Z');bt.ME=bt.MS+72*24*H;bt.N_M=(bt.ME-bt.MS)//M;bt.N_H=bt.N_M//12
bt.PERIODS={'PRE':(bt.MS+10*24*H,bt.ME)}
N=bt.N_M;H0=0;SYMS=bt.SYMS
p={'status':'RESEARCH_ONLY_SYNTHETIC_STANDALONE_R21_NOT_FULL_RUNNER','source_sha256':hashlib.sha256(src.read_bytes()).hexdigest(),'design':'6 market regimes x 2 seeds; 72d paths, first10d warmup; 13 alts + BTC, correlated 5m innovations; separate ASTER/Binance contemporaneous taker imbalance, correlated noisy latent flow, no deliberately predictive future returns; each venue own noise, volumes. Synthetic flow distribution illustrative not calibrated execution.','arms':['R18','R21'],'logic':'Reconstruct old downside fresh break: completed D/12/6 bear, rel6<0, prior12h low break .1ATR; R18 reject BTC24/72 bullish and decline>2ATR, R21 bearish BTC24/72 additional room>=.5ATR and (Binance 3h sell or BTC week up). New route ASTER 3h buy imbalance>=.15, 3h volume ratio>=1.5, price decline; one ranked short each3h; subsequent closed H1 bearish lower than origin open within3h; QA. OLD H24, NEW H48 TP8, STOP8, 2 slots .30 gross, 12h cooldown, 10/30bps. No funding. Generated data not actual venue nor peer runners.','regimes':['BULL','BULL_PULLBACK','BEAR','RANGE','SQUEEZE','REVERSAL'],'seeds':[202611272401,202611272402]}
P.write_text(json.dumps(p,indent=2),encoding='utf8')
def market(reg,seed):
 rng=np.random.default_rng(seed);d=np.arange(N)/288
 drift={'BULL':.004,'BULL_PULLBACK':.003,'BEAR':-.004,'RANGE':0,'SQUEEZE':.001,'REVERSAL':.005}[reg]
 vol={'BULL':.025,'BULL_PULLBACK':.045,'BEAR':.04,'RANGE':.035,'SQUEEZE':.055,'REVERSAL':.045}[reg]
 mu=np.full(N,drift/288)
 if reg=='REVERSAL':mu[d>=36]=-.007/288
 if reg in ('BULL_PULLBACK','RANGE','SQUEEZE'):mu+=.004*np.sin(2*np.pi*d/10)/288
 jump=np.zeros(N)
 if reg=='SQUEEZE':
  k=rng.choice(np.arange(288,N),size=8,replace=False);jump[k]=rng.choice([-.04,.055],size=len(k))
 common=rng.standard_normal(N);hs={};ms={};af={};bf={}
 for j,sym in enumerate(SYMS):
  innovation=common if j==0 else .65*common+math.sqrt(1-.65**2)*rng.standard_normal(N)
  ret=mu*(1+.03*j)+vol*(1+.035*j)*innovation/math.sqrt(288)+jump*(1+.03*j)
  cl=(100+5*j)*np.exp(np.cumsum(ret));op=np.r_[100+5*j,cl[:-1]];wig=np.maximum(.00007,.18*np.abs(ret))
  v=1000*np.exp(.65*rng.standard_normal(N))*(1+100*np.abs(ret))
  m=np.c_[op,np.maximum(op,cl)*(1+wig),np.minimum(op,cl)*(1-wig),cl,v];rr=m.reshape(-1,12,5)
  h=np.c_[rr[:,0,0],rr[:,:,1].max(1),rr[:,:,2].min(1),rr[:,-1,3],rr[:,:,4].sum(1)]
  # correlated contemporaneous order flow, independent venue perturbations, no future use
  ret_h=ret.reshape(-1,12).sum(1);latent=.18*np.tanh(ret_h/(vol/math.sqrt(24)))+.22*rng.standard_normal(len(h))
  a=np.clip(latent+.15*rng.standard_normal(len(h)),-.85,.85)
  b=np.clip(.65*latent+.12*rng.standard_normal(len(h)),-.85,.85)
  # venue volume activity pulses, independent of future returns
  burst=np.exp(.55*rng.standard_normal(len(h)));av=h[:,4]*burst;bv=h[:,4]*np.exp(.35*rng.standard_normal(len(h)))
  h[:,4]=av
  m[:,4]*=np.repeat(burst,12)
  hs[sym]=h;ms[sym]=m;af[sym]=np.c_[av,av*(1+a)/2];bf[sym]=np.c_[bv,bv*(1+b)/2]
 return hs,ms,af,bf
def trade(x,ms):
 m=ms[x['symbol']];i=(x['entryTs']-bt.MS)//M;h=24 if x['route']=='OLD24' else 48;j=i+12*h
 if j>=len(m):return None
 ep=float(m[i,0]);stop=ep*1.08;target=ep*.92
 sh=np.flatnonzero(m[i:j,1]>=stop);th=np.flatnonzero(m[i:j,2]<=target) if h==48 else []
 si=int(sh[0]) if len(sh) else j-i;ti=int(th[0]) if len(th) else j-i
 xp=float(m[j,0]);e=bt.MS+j*M;why='TIME'+str(h)
 if si<=ti and si<j-i:xp=float(max(m[i+si,0],stop));e=bt.MS+(i+si+1)*M;why='HARD_STOP8'
 elif ti<j-i:xp=target;e=bt.MS+(i+ti+1)*M;why='TARGET'
 return {**x,'period':'PRE','direction':'SHORT','entry':ep,'exitPrice':xp,'exitTs':e,'rawReturn':1-xp/ep,'exitReason':why}
def flow(f,i,n):
 z=f[i-n:i];return float(2*z[:,1].sum()/z[:,0].sum()-1)
def d126(h,i):
 vals=[]
 for n in (24,12,6):
  j=i//n*n;vals.append(h[j-1,3]/h[j-n-1,3]-1)
 return all(x<0 for x in vals)
def evaluate(reg,seed):
 hs,ms,af,bf=market(reg,seed);b=hs['BTC'];old=[];old21=[];new_candidates={}
 for sym in SYMS[1:]:
  h=hs[sym];m=ms[sym];qa=r3.prepare_qa(h,m)[0]
  for i in range(240,len(h)-48):
   t=bt.HS+i*H
   if not qa[i]:continue
   atr=r3.calc_atr(h,i)
   if not atr or atr<=0:continue
   c=h[i-1,3];b24=b[i-1,3]/b[i-25,3]-1;b72=b[i-1,3]/b[i-73,3]-1;bear=b24<0 and b72<0
   rel6=c/h[i-7,3]-b[i-1,3]/b[i-7,3]
   if d126(h,i) and rel6<0 and c<h[i-13:i-1,2].min()-.1*atr and not(b24>0 and b72>0) and (h[i-4,3]-c)/atr<=2:
    x=dict(symbol=sym,entryTs=t,route='OLD24');z=trade(x,ms)
    if z:
     old.append(z);room=(c-h[i-169:i-1,2].min())/atr;week=b[i-1,3]/b[i-169,3]-1
     if not bear or (room>=.5 and (flow(bf[sym],i,3)<0 or week>0)):old21.append(z)
   if i%3==0:
    im=flow(af[sym],i,3);vr=af[sym][i-3:i,0].mean()/af[sym][i-24:i-3,0].mean()
    if im>=.15 and vr>=1.5 and c<h[i-4,3]:
     score=im*min(vr,10)
     if t not in new_candidates or (score,sym)>new_candidates[t][:2]:new_candidates[t]=(score,sym,i)
 new=[]
 for t,(score,sym,i) in new_candidates.items():
  h=hs[sym];ep=ms[sym][i*12,0];qa=r3.prepare_qa(h,ms[sym])[0]
  for j in range(i+1,i+4):
   if j>=len(h) or not qa[j]:continue
   if h[j-1,3]<ep and h[j-1,3]<h[j-1,0]:
    z=trade(dict(symbol=sym,entryTs=bt.HS+j*H,route='NEW48'),ms)
    if z:new.append(z)
    break
 new=list({(x['symbol'],x['entryTs']):x for x in new}.values())
 q={'regime':reg,'seed':seed,'btc_return_pct':float(100*(b[-1,3]/b[240,0]-1)),'old_candidates':len(old),'r21_old_candidates':len(old21),'new_candidates':len(new),'results':{}}
 for arm,cs in [('R18',old+new),('R21',old21+new)]:
  q['results'][arm]={}
  for fee in (10,30):
   z=bt.wallet(cs,'PRE',fee,ms);z.pop('accepted',None);q['results'][arm][str(fee)]=z
 print('SYNTH',reg,seed,round(q['btc_return_pct'],2),len(old),len(old21),len(new),[(k,round(v['30']['terminal_jpy']),round(v['30']['max_dd_pct'],2),v['30']['n']) for k,v in q['results'].items()],flush=True)
 return q
records=[]
for reg in p['regimes']:
 for seed in p['seeds']:
  records.append(evaluate(reg,seed))
  O.write_text(json.dumps({'protocol':p,'records':records},indent=2,allow_nan=False,default=lambda x:x.item()),encoding='utf8')
print('SAVED',hashlib.sha256(O.read_bytes()).hexdigest(),flush=True)
